        Phrase.GREETING_SUB to "Silapha ngenxa yakho. Nangebanga labantu obathandako.",
        Phrase.TAGLINE to "Irhelebho. Amaphilo. Ikhaya.",
        Phrase.PREVIEW_BADGE to "Isibonelo somklamo · Idatha eyenziweko",
        Phrase.LANGUAGE to "Ilimi",
